import {PARTS} from './catalog.js';import {loadFlight,saveFlight} from './flight-save.js';import {fleet,canControl,selectVessel} from './fleet.js';
const anchor=v=> (v.parts.find(p=>PARTS[p.type].control)||v.parts[0]).id;
export function trackingList(record){if(!record)return [];const root=loadFlight(record);try{return fleet(root).map((v,i)=>({id:anchor(v),name:(v.vesselName||record.meta?.name||'飛行')+(i===0?' / 操作中':''),parts:v.parts.length,altitude:v.orbit.altitude,speed:v.vel.length(),time:v.time,controllable:canControl(v),status:v.crashed?'損傷':v.landed?'着地':v.orbit.stable?'周回軌道':'飛行中'}));}finally{root.dispose();}}
export function trackedFlight(record,partId,observe=false){let root=loadFlight(record);try{const target=fleet(root).find(v=>v.parts.some(p=>p.id===partId));if(!target)throw Error('選択した機体が見つかりません');if(!observe)root=selectVessel(root,target);return {record:saveFlight(root,{...record.meta,name:root.vesselName||record.meta?.name,pilot:null}),observe:observe?partId:null};}finally{root.dispose();}}
